mapper.update:
update community_notice
title = #{title}, content = #{content}, type = #{type}, cover_image = #{coverImage}, is_top = #{isTop}, view_count = #{viewCount}, status = #{status},
where id = #{id}

mapper.select:
select * from community_notice

    and title like concat('%', #{title}, '%')
    and type = #{type}
    and status = #{status}

order by is_top desc, publish_time desc
